import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';
import * as React from 'react';
import ReactDOM from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import {CpuLoadChart} from '../src/monitoring/CpuLoadChart';
import {createMockCpuLoadSource} from '../src/monitoring/mockCpuLoadSource';

// leak counters
const w = window as any;
w.__timers = new Set();
const si = window.setInterval, ci = window.clearInterval;
(window as any).setInterval = (...a: any[]) => { const id = si(...(a as [any])); w.__timers.add(id); return id; };
(window as any).clearInterval = (id: any) => { w.__timers.delete(id); ci(id); };
w.__ro = 0;
const RO = window.ResizeObserver;
(window as any).ResizeObserver = class extends RO { constructor(cb: any) { super(cb); w.__ro++; } disconnect() { w.__ro--; super.disconnect(); } };

const source = createMockCpuLoadSource();
function Harness() {
  const [theme, setTheme] = React.useState<'light' | 'dark'>('light');
  const [mounted, setMounted] = React.useState(true);
  const [width, setWidth] = React.useState('100%');
  w.__setTheme = setTheme; w.__setMounted = setMounted; w.__setWidth = setWidth;
  return (
    <ThemeProvider theme={theme}>
      <div style={{padding: 24, width, height: 460, boxSizing: 'border-box'}}>
        {mounted && <CpuLoadChart source={source} />}
      </div>
    </ThemeProvider>
  );
}
ReactDOM.createRoot(document.getElementById('root')!).render(<React.StrictMode><Harness /></React.StrictMode>);
